{
  "source_id": "TEXT",
  "cast": [
    {"id": "P01", "name": "郑庄公"},
    {"id": "P02", "name": "武姜"},
    {"id": "P03", "name": "共叔段"},
    {"id": "P04", "name": "祭仲"},
    {"id": "P05", "name": "公子吕"},
    {"id": "P06", "name": "颍考叔"}
  ],
  "locations": [
    {"id": "L01", "name": "宫廷"},
    {"id": "L02", "name": "京城"},
    {"id": "L03", "name": "鄢"},
    {"id": "L04", "name": "城颍"},
    {"id": "L05", "name": "颍谷"},
    {"id": "L06", "name": "大隧"}
  ],
  "scenes": [
    {
      "sceneId": "L01",
      "characters": ["P01", "P02", "P03", "P04"],
      "flow": [
        {"action": "武姜向庄公请封制邑。"},
        {"speaker": "P02", "line": "请把制邑给共叔段。", "mode": "spoken"},
        {"speaker": "P01", "line": "制邑是险要之地，虢叔死在那里，其他地方我都可以答应。", "mode": "spoken"},
        {"speaker": "P02", "line": "那就请京邑吧。", "mode": "spoken"},
        {"action": "庄公同意，共叔段迁居京城，被称为京城大叔。"},
        {"speaker": "P04", "line": "都城超过百雉，是国家祸害。先王制度：大都不过国都三分之一，中等五分之一，小九分之一。今京邑不合制度，君将不堪。", "mode": "spoken"},
        {"speaker": "P01", "line": "姜氏想要，怎么能避害？", "mode": "spoken"},
        {"speaker": "P04", "line": "姜氏有什么满足？不如早做打算，不要让滋长蔓延！", "mode": "spoken"},
        {"speaker": "P01", "line": "多行不义必自毙，你姑且等着。", "mode": "spoken"}
      ]
    },
    {
      "sceneId": "L01",
      "characters": ["P01", "P05"],
      "flow": [
        {"action": "共叔段命令西鄙、北鄙归附自己。"},
        {"speaker": "P05", "line": "国家不堪双重，您怎么办？想给大叔，我请侍奉他；不想给，请除掉他，不要生民心。", "mode": "spoken"},
        {"speaker": "P01", "line": "不用，将自及。", "mode": "spoken"},
        {"action": "共叔段收编两地，扩展到廪延。"},
        {"speaker": "P05", "line": "可以了，势力厚将得众。", "mode": "spoken"},
        {"speaker": "P01", "line": "不义不昵，势力厚将崩溃。", "mode": "spoken"}
      ]
    },
    {
      "sceneId": "L03",
      "characters": ["P01", "P05", "P03"],
      "flow": [
        {"action": "共叔段整顿军队，准备袭击郑国。"},
        {"action": "庄公得知袭击日期。"},
        {"speaker": "P01", "line": "可以了。", "mode": "spoken"},
        {"action": "庄公命公子吕率军二百乘伐京。"},
        {"action": "京城背叛共叔段。"},
        {"action": "共叔段逃入鄢。"},
        {"action": "庄公讨伐鄢。"},
        {"action": "共叔段出奔共。"}
      ]
    },
    {
      "sceneId": "L04",
      "characters": ["P01", "P02"],
      "flow": [
        {"action": "庄公将武姜安置在城颍。"},
        {"speaker": "P01", "line": "不到黄泉，不再相见。", "mode": "spoken"},
        {"action": "庄公后来后悔。"}
      ]
    },
    {
      "sceneId": "L05",
      "characters": ["P01", "P06"],
      "flow": [
        {"action": "颍考叔听说后，向庄公献礼。"},
        {"action": "庄公赐宴。"},
        {"action": "颍考叔吃饭时留肉不吃。"},
        {"speaker": "P01", "line": "为何留肉？", "mode": "spoken"},
        {"speaker": "P06", "line": "小人有母，都尝过小人的食物，未尝君之羹，请让我带回去给她。", "mode": "spoken"},
        {"speaker": "P01", "line": "你有母亲可送，唯独我没有！", "mode": "spoken"},
        {"speaker": "P06", "line": "请问何意？", "mode": "spoken"},
        {"speaker": "P01", "line": "我告知缘故，且说后悔。", "mode": "spoken"},
        {"speaker": "P06", "line": "君何患？若挖地及泉，隧道相见，谁说不行？", "mode": "spoken"},
        {"action": "庄公听从。"}
      ]
    },
    {
      "sceneId": "L06",
      "characters": ["P01", "P02"],
      "flow": [
        {"action": "庄公进入隧道赋诗。"},
        {"speaker": "P01", "line": "大隧之中，其乐融融。", "mode": "spoken"},
        {"action": "武姜走出隧道赋诗。"},
        {"speaker": "P02", "line": "大隧之外，其乐泄泄。", "mode": "spoken"},
        {"action": "母子和好如初。"}
      ]
    }
  ]
}

